function navigation(){K.headers={};K.menus={};for(const [size,w,pad]of [['Desktop',1440,48],['Tablet',768,32],['Mobile',390,20]]){const f=box('Header',w,'HORIZONTAL',16,pad,'paper');val(f,'paddingTop',12);val(f,'paddingBottom',12);f.counterAxisAlignItems='CENTER';f.primaryAxisAlignItems='SPACE_BETWEEN';const l=put(f,logo(size==='Mobile'?130:152));l.name='Home logo';const nav=put(f,box('Nav',size==='Desktop'?476:114,'HORIZONTAL',16));nav.counterAxisAlignItems='CENTER';if(size==='Desktop'){for(const title of ['Услуги','Команда','Заявка']){const b=put(nav,button(title,title==='Заявка'?148:148,'Default',title==='Заявка'?'Primary':'Link'));b.name='Nav / '+title;}}else{const b=put(nav,button('Меню',114,'Default','Secondary'));b.name='Menu toggle';}const c=master(f,'Header/'+size);place(c);K.headers[size]=c;if(size!=='Desktop'){const menu=box('Menu',w,'VERTICAL',8,pad,'paper');const closeBtn=put(menu,button('Закрыть',w-2*pad,'Default','Secondary'),true);closeBtn.name='Menu close';for(const title of ['Услуги','Работы','Команда','Заявка']){const b=put(menu,button(title,w-2*pad),true);b.name='Menu / '+title;}const mc=master(menu,'Menu/'+size);place(mc);K.menus[size]=mc;}}
}
