function grid(parent,items,columns,width,gap){const out=put(parent,box('Grid / '+columns+' columns',width,'VERTICAL',gap),true);for(let i=0;i<items.length;i+=columns){const row=put(out,box('Row',width,'HORIZONTAL',gap),true);for(const n of items.slice(i,i+columns))put(row,n,true);}return out;}
function footer(root,size){const d=sizes[size],iw=d.w-d.p*2;const f=section(root,'Footer',size);val(f,'paddingTop',32);val(f,'paddingBottom',32);put(f,rule(iw),true);const row=put(f,box('Footer / Content',iw,size==='Desktop'?'HORIZONTAL':'VERTICAL',24),true);put(row,logo(152));const t=put(row,box('Location',size==='Desktop'?660:iw,'VERTICAL',4),true);label(t,'Нижний Новгород',iw,16,'Bold');label(t,'Работаем по всей России',iw,14,'Regular','muted');if(size==='Desktop'){const c=put(row,box('Copyright',220,'VERTICAL',0));label(c,'ЗАЦЕП © 2026',220,14,'Bold');}else label(row,'ЗАЦЕП © 2026',iw,14,'Bold');}
function rootFrame(title,size,x,y){const d=sizes[size],r=box(title+' · '+d.w,d.w,'VERTICAL',0,0,'paper');product.appendChild(r);r.x=x;r.y=y;r.layoutGrids=d.cols===1?[]:[{pattern:'COLUMNS',alignment:'STRETCH',gutterSize:d.g,count:d.cols,offset:d.p,visible:false,color:{...rgb(P.lime),a:.08}}];put(r,instance(K.headers[size]),true);return r;}
function home(size,x,y){const d=sizes[size],iw=d.w-d.p*2,m=size==='Mobile',desk=size==='Desktop';const r=rootFrame('Лендинг',size,x,y);const hero=section(r,'Hero',size);val(hero,'paddingTop',desk?48:32);val(hero,'paddingBottom',32);const row=put(hero,box('Hero / Composition',iw,desk?'HORIZONTAL':'VERTICAL',24),true);const copy=put(row,box('Hero / Offer',desk?888:iw,'VERTICAL',24,desk?40:0),desk);if(desk){fix(copy,888,552);copy.primaryAxisAlignItems='CENTER';border(copy,'ink',2);}const cw=desk?808:iw;label(copy,'ЗАЦЕП / КОНТЕНТ-АГЕНТСТВО',cw,12,'Bold');label(copy,'Контент,\nкоторый цепляет.',cw,d.h1,'Bold','ink',true,d.h1*1.25);label(copy,'Стратегия, Reels, дизайн и таргет в одной системе продвижения.',cw,desk?20:18);put(copy,button('Обсудить задачу',m?iw:296),m);put(row,media(desk?432:iw,desk?552:m?400:520,'hero-collage','Hero / Collage'),!desk);const stripe=put(hero,box('Geography',iw,desk?'HORIZONTAL':'VERTICAL',8,16,'lime'),true);border(stripe);label(stripe,'НИЖНИЙ НОВГОРОД',desk?500:iw-32,12,'Bold');label(stripe,'РАБОТАЕМ ПО ВСЕЙ РОССИИ',desk?812:iw-32,12,'Bold');
const services=section(r,'Услуги',size);sectionHeading(services,'01 / УСЛУГИ','Когда контент есть.\nА системы нет.',size);const pain=put(services,box('Problems',iw,desk?'HORIZONTAL':'VERTICAL',24),true);for(const[a,b]of [['Соцсети рывками','Нет единого ритма публикаций.'],['Визуал распадается','Бренд выглядит по-разному.'],['Реклама отдельно','Контент и продвижение не связаны.']]){const q=put(pain,box(a,desk?432:iw,'VERTICAL',12),true);put(q,rule(q.width),true);label(q,a,q.width,20,'Bold');label(q,b,q.width,16,'Regular','muted');}label(services,'Собираем в одну систему.',iw,desk?28:24,'Bold','ink',true);if(desk)put(services,instance(K.decks.services[0]),true);else{const a=put(services,box('Services / Accordion list',iw,'VERTICAL',8),true);K.accordions.services.forEach((v,i)=>put(a,instance(v[i===0?1:0],iw),true));}
const work=section(r,'Работы',size);sectionHeading(work,'02 / РАБОТЫ','Показываем,\nкак может цеплять.',size);label(work,'Демонстрационные концепции. Они показывают подход к визуалу и содержанию.',iw,16,'Regular','muted');const featured=put(work,instance(K.cards.Featured,iw),true);featured.name='Work / Featured';const pic=featured.findOne(n=>n.name==='Media');if(pic)pic.resize(iw,desk?560:m?300:400);grid(work,[instance(K.cards.Content,(iw-d.g)/(m?1:2)),instance(K.cards.Launch,(iw-d.g)/(m?1:2))],m?1:2,iw,d.g);
const proc=section(r,'Процесс',size);sectionHeading(proc,'03 / ПРОЦЕСС','Понятно, что дальше.',size);const cols=desk?4:m?1:2,cellWidth=(iw-(cols-1)*d.g)/cols;grid(proc,steps.map((v,i)=>instance(K.step.Step,cellWidth,{Title:v[0],Body:v[1],Number:'0'+(i+1)})),cols,iw,d.g);label(proc,'Формат под вашу задачу.',iw,desk?28:24,'Bold','ink',true);grid(proc,formats.map(v=>instance(K.step.Format,cellWidth,{Title:v[0],Body:v[1]})),cols,iw,d.g);
const team=section(r,'Команда',size);sectionHeading(team,'04 / КОМАНДА','За проектом\nстоят роли.',size);label(team,'Одна задача. Общий контекст. Понятная ответственность.',iw,desk?20:18);label(team,'Это функции в проекте. Состав команды зависит от задачи.',iw,14,'Regular','muted');if(desk)put(team,instance(K.decks.roles[0]),true);else{const a=put(team,box('Roles / Accordion list',iw,'VERTICAL',8),true);K.accordions.roles.forEach((v,i)=>put(a,instance(v[i===0?1:0],iw),true));}
const questions=section(r,'Вопросы',size);sectionHeading(questions,'05 / ВОПРОСЫ','Коротко о важном.',size);const faqList=put(questions,box('FAQ / List',iw,'VERTICAL',8),true);K.accordions.faq.forEach(v=>put(faqList,instance(v[0],iw),true));
const brief=section(r,'Заявка',size,'lime');const br=put(brief,box('Brief / Layout',iw,desk?'HORIZONTAL':'VERTICAL',desk?48:32),true);const offer=put(br,box('Brief / Offer',desk?636:iw,'VERTICAL',24),desk);label(offer,'06 / ЗАЯВКА',offer.width,12,'Bold');label(offer,'Найдём,\nчем зацепить.',offer.width,m?32:desk?48:40,'Bold','ink',true);label(offer,'Расскажите о задаче. Уточним детали и предложим подходящий формат.',offer.width,18);label(offer,'* Обязательные поля',offer.width,12,'Regular','muted');put(br,instance(K.forms[size][0]),!desk);footer(r,size);S.screens['home'+size]=r.id;return r;}
function casePage(size,x,y){const d=sizes[size],iw=d.w-2*d.p,m=size==='Mobile',desk=size==='Desktop';const r=rootFrame('Кейс',size,x,y);const intro=section(r,'Case / Intro',size);val(intro,'paddingTop',desk?48:32);const back=put(intro,button('Вернуться к работам',m?iw:296,'Default','Link'));back.name='Case / Back';label(intro,'ДЕМО-КЕЙС / REELS И КОНТЕНТ',iw,12,'Bold');label(intro,'Серия, которая\nдержит внимание.',iw,desk?56:d.h1,'Bold','ink',true);label(intro,'Демонстрационная концепция: один визуальный приём объединяет разные сюжеты.',iw,18);put(intro,media(iw,desk?600:m?400:460,'hero-collage','Case / Hero'),true);
const task=section(r,'Case / Task',size);sectionHeading(task,'01 / ЗАДАЧА','Узнаваемость\nс первого кадра.',size);label(task,'Показать, как контент сохраняет характер бренда ещё до появления логотипа.',iw,18);const idea=section(r,'Case / Idea',size,'lime');sectionHeading(idea,'02 / ИДЕЯ','Один визуальный зацеп.\nМного сюжетов.',size);label(idea,'Повторяемый графический жест связывает ролики в серию. Меняются темы и ритм; остаются голос и узнаваемая графика.',iw,18);const deliver=section(r,'Case / Deliverables',size);sectionHeading(deliver,'03 / ВЫПОЛНЕННЫЕ РАБОТЫ','Правила для серии.',size);const list=put(deliver,box('Deliverables / List',iw,'VERTICAL',20),true);for(const[a,b]of [['01 / Сценарный каркас','Единая логика начала, развития и завершения короткого ролика.'],['02 / Обложки и титры','Типографика, акценты и композиция в фирменном характере.'],['03 / Правила монтажа','Ритм, переходы и адаптации под вертикальный формат.']]){const q=put(list,box(a,iw,'VERTICAL',12),true);put(q,rule(iw),true);label(q,a,iw,20,'Bold');label(q,b,iw,16);}
const mat=section(r,'Case / Materials',size);sectionHeading(mat,'04 / МАТЕРИАЛЫ','Один приём.\nРазный ритм.',size);const gallery=put(mat,box('Case / Gallery',iw,m?'VERTICAL':'HORIZONTAL',d.g),true);put(gallery,media(m?iw:(iw-d.g)/3,m?440:560,'reels-frame','Vertical frame'),m);put(gallery,media(m?iw:(iw-d.g)*2/3,m?300:560,'editing-collage','Editing collage'),true);const result=section(r,'Case / Result',size);sectionHeading(result,'05 / РЕЗУЛЬТАТ','Цельная система\nдля производства.',size);label(result,'Зафиксированы визуальный принцип серии, сценарный каркас и правила применения. Это демонстрационный проект; клиентские показатели не заявляются.',iw,18);const cta=section(r,'Case / Inquiry',size,'lime');sectionHeading(cta,'06 / ЗАЯВКА','Есть похожая задача?',size);put(cta,button('Обсудить задачу',m?iw:296),m);footer(r,size);S.screens['case'+size]=r.id;return r;}
function notes(){const f=box('Разработка · правила и согласования',1440,'VERTICAL',32,48,'paper');product.appendChild(f);f.x=80;f.y=80;label(f,'ПЕРЕДАЧА В РАЗРАБОТКУ',1344,36,'Bold','ink',true);const data=[['Адаптация','≥ 1024 px: 12 колонок, поля 48, gap 24. 600–1023 px: 8 колонок, поля 32, gap 20. < 600 px: 1 колонка, поля 20. Контент fluid; максимальная ширина 1440. Ниже 1024: меню, оффер перед визуалом, услуги и роли как аккордеоны.'],['Компоненты','Все Product/* независимы от исходных вайрфреймов. Вложенные элементы растягиваются через Fill; высота текстовых блоков Hug. Заголовки, подписи и значения изменяются в свойствах. Иконки в кнопках доступны через Instance swap.'],['Поведение','Услуги и роли на desktop: один выбранный пункт. На mobile/tablet: независимое раскрытие с ответом под заголовком; изначально SMM и таргетолог открыты. FAQ по умолчанию закрыт. Меню открывается поверх экрана, крестик возвращает в контекст.'],['Форма','Обязательны имя, контакт, задача и согласие. Компания необязательна. На blur проверять пустое значение; для контакта разрешить телефон или Telegram. Ошибка рядом с полем, фокус в первом ошибочном. При отправке блокировать повторное нажатие. При сбое сохранить значения и дать повтор.'],['Прототип','Поля показывают заранее заданный пример по нажатию. Пустая отправка → ошибки; заполненная → отправка → успех. Сбой и повтор доступны отдельной точкой старта. Никакие данные не отправляются. Переходы 240 мс ease-out; prefers-reduced-motion: 0 мс, без Smart Animate.'],['Графика и доступность','Логотип и знак экспортировать SVG; коллажи PNG/WebP 1×/2×, object-fit: cover. Основной текст ≥ 4,5:1; зоны нажатия ≥ 44 px. Фокус: видимый контур. Кнопки реализовать button, меню nav, аккордеоны button + aria-expanded.'],['До публикации согласовать','Контакты, URL политики обработки данных и юридический текст согласия. Кейсы демонстрационные; реальные клиенты, показатели и отзывы не добавлены. Роли обозначают функции, а не подтверждённый штат. Брендбук и локальный сайт не изменены.']];for(const[a,b]of data){label(f,a,1344,20,'Bold');label(f,b,1344,16);}S.notes=f.id;return f;}
async function build(){await restore();await figma.setCurrentPageAsync(product);const nodes=new Map(product.findAll(()=>true).map(n=>[n.id,n]));for(const size of Object.keys(sizes)){const homeView=nodes.get(S.prototypes['home'+size]);for(const root of product.children.filter(n=>n.type==='FRAME')){if(root.width!==sizes[size].w)continue;for(const n of root.findAll(n=>n.name==='Home logo')){if(root.id===homeView.id)link(n,homeView.findOne(x=>x.type==='FRAME'&&x.name==='Hero'),'SCROLL_TO');else link(n,homeView,'NAVIGATE');}}}for(const id of Object.values(S.screens)){const r=nodes.get(id);for(const t of r.findAll(n=>n.type==='TEXT'&&n.fontSize===18&&n.fontName.family==='Manrope'))t.maxWidth=840;}
for(const c of kit.findAll(n=>n.type==='COMPONENT'&&n.name==='State=Focus')){if(c.findOne(n=>n.name==='Focus ring'))continue;const ring=track(figma.createRectangle());ring.name='Focus ring';ring.fills=[];border(ring,'ink',2);c.appendChild(ring);ring.layoutPositioning='ABSOLUTE';ring.resize(c.width+8,c.height+8);ring.x=-4;ring.y=-4;ring.constraints={horizontal:'STRETCH',vertical:'STRETCH'};}
await flush();save('product-complete.json',{S,K:serialize(K)});const exports=[];for(const[key,id]of Object.entries(S.screens))exports.push([key,nodes.get(id),.45]);for(const size of Object.keys(sizes)){const home=nodes.get(S.screens['home'+size]);exports.push(['hero'+size,home.children[1],size==='Mobile'?1:.8],['services'+size,home.children[2],size==='Mobile'?1:.7]);}for(let i=0;i<S.identityBoards.length;i++)exports.push(['identity'+i,await figma.getNodeByIdAsync(S.identityBoards[i]),.65]);exports.push(['kit-foundations',await figma.getNodeByIdAsync(S.foundations),.65]);await Promise.all(exports.map(async([key,n,scale])=>{const b=await n.exportAsync({format:'PNG',constraint:{type:'SCALE',value:scale}});figma.ui.postMessage({type:'image',name:'product-'+key+'.png',bytes:Array.from(b)});}));save('product-export-done.json',{ok:true});figma.currentPage.selection=[nodes.get(S.screens.homeDesktop)];figma.viewport.scrollAndZoomIntoView([nodes.get(S.screens.homeDesktop).children[1]]);log('Экспорт для проверки готов.');}
figma.ui.onmessage=async m=>{if(m.type==='close')figma.closePlugin();if(m.type==='build')try{await build();}catch(e){save('product-finish-error.json',{error:String(e),stack:e.stack,S,K:serialize(K)});log('Ошибка: '+String(e));}};figma.ui.postMessage({type:'ready'});
